import shieldCompactRaw from "./zatca-shield-compact.svg?raw";

const BRAND_NAVY = "#17365d";

/**
 * The shield artwork's own viewBox is 512x512, but its silhouette only
 * occupies this sub-rectangle (see the `M96 64 L416 64 ...` path in
 * zatca-shield.svg / zatca-shield-compact.svg). Framing the nested <svg>'s
 * viewBox to exactly this box means `preserveAspectRatio="xMidYMid meet"`
 * scales and centers the shield itself, not its surrounding empty space.
 */
const SHIELD_BOUNDS = { x: 96, y: 64, width: 320, height: 416 };

/**
 * Strips the outer `<svg ...>` / `</svg>` wrapper from a raw SVG source,
 * leaving only its inner markup (defs + drawing) so it can be re-embedded
 * inside a nested `<svg>` element without a doubled root tag.
 */
function innerMarkup(rawSvg: string): string {
  return rawSvg.replace(/^[\s\S]*?<svg[^>]*>/, "").replace(/<\/svg>\s*$/, "");
}

/**
 * Composes a shield mark onto a solid navy square tile, with `paddingRatio`
 * of empty margin on every side (e.g. 0.12 = 12% padding per edge). Returns
 * a self-contained `data:image/svg+xml` URI — used only for the favicon, which
 * (unlike manifest icons) is a normal HTML `<link rel="icon">` and renders SVG
 * fine in every browser. See organization.ts for the same encoding precedent
 * (VIS-05: bundled locally, never network-dependent).
 */
function composeIconUri(rawSvg: string, paddingRatio: number, size = 512): string {
  const pad = size * paddingRatio;
  const contentSize = size - pad * 2;
  const { x, y, width, height } = SHIELD_BOUNDS;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
  <rect width="${size}" height="${size}" fill="${BRAND_NAVY}" />
  <svg x="${pad}" y="${pad}" width="${contentSize}" height="${contentSize}" viewBox="${x} ${y} ${width} ${height}" preserveAspectRatio="xMidYMid meet">
    ${innerMarkup(rawSvg)}
  </svg>
</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

/**
 * App icons for the web app manifest, plus the browser-tab favicon.
 *
 * The three manifest icons (icon192, icon512, icon512Maskable) are
 * committed PNG data URIs, NOT composed at runtime. Chrome's manifest icon
 * pipeline rejects SVG outright — verified 2026-08-11 via DevTools ->
 * Application -> Manifest on a properly served http://localhost:5173
 * origin, which reported every SVG manifest icon as "failed to load" and
 * flagged the missing square icon requirement. (An earlier check using
 * `new Image()` in page context reported success, but that only proves the
 * page renderer can draw an SVG — it never exercises Chrome's manifest icon
 * decoder, so it was a false pass. Don't repeat that check as evidence a
 * manifest icon works.)
 *
 * How these PNGs were produced (regenerate the same way if the shield
 * artwork or padding ever changes):
 *   1. In a browser page (e.g. the dev server), build the same composed SVG
 *      markup that `composeIconUri` below produces — navy tile + shield
 *      artwork inset by the padding ratio noted on each constant.
 *   2. Load that SVG data URI into a `new Image()`, draw it onto a
 *      `<canvas>` sized to the target pixel dimensions (192, 512, 512).
 *   3. Quantize each RGB channel to 12 levels (round to the nearest of
 *      255/11 steps via `getImageData`/`putImageData`) before encoding —
 *      the raw rasterized PNGs blew the bundle-size budget
 *      (`npm run check:bundle-size`) by ~130 kB; quantizing cuts the
 *      diagonal-stripe-gradient artwork's PNG size by ~2/3 with no visible
 *      banding at icon scale, since it collapses near-duplicate
 *      anti-aliased edge colors into runs the PNG deflate step compresses
 *      well. Skip this step only if a future budget has enough headroom.
 *   4. Read back `canvas.toDataURL("image/png")` and paste the resulting
 *      base64 string in as the constant below.
 * Padding ratios: icon192 and icon512 use 12% padding; icon512Maskable uses
 * 20% so all shield content stays inside the ~80% "safe zone" circle that OS
 * icon masks crop to (the full-detail shield's own `composeIconUri` calls
 * were removed along with those runtime compositions — `composeIconUri`
 * below is now used only for the favicon).
 */
export const APP_ICONS = {
  /** 192x192 PNG, shield on navy, 12% padding. */
  icon192:
    "data:image/png;base64,",
  /** 512x512 PNG, shield on navy, 12% padding. */
  icon512:
    "data:image/png;base64,",
  /** 512x512 PNG, shield on navy, 20% padding (maskable safe zone). */
  icon512Maskable:
    "data:image/png;base64,",
  /**
   * Compact (fewer, thicker stripes) variant, tight padding, for the
   * browser-tab favicon where the full-detail mark would smudge. Stays SVG:
   * the `<link rel="icon">` literal in index.html is a normal HTML favicon,
   * not a manifest icon, and every browser renders SVG there fine.
   *
   * Has one manual downstream consumer: the `<link rel="icon">` literal in
   * index.html, which cannot import this TS module and hand-mirrors this
   * exact output instead. If this composition ever changes (artwork,
   * padding, or size), regenerate that literal too — see the sync comment
   * above the `<link>` tag in index.html for the other half of this note.
   */
  faviconSvg: composeIconUri(shieldCompactRaw, 0.08, 96),
} as const;
